def circular_minimax_partition(values: list, groups: int) -> int:
    """
    Values are non-negative integers arranged in a circle. Cut the circle
    into exactly `groups` nonempty contiguous segments. Segment sums include
    every value exactly once. Return the smallest possible value of the
    largest segment sum.
    """
    n = len(values)
    if groups == 1:
        return sum(values)
    if groups == n:
        return max(values)

    def can_partition(target, start_idx):
        count = 0
        current_sum = 0
        elements_covered = 0
        i = 0
        while elements_covered < n:
            val = values[(start_idx + i) % n]
            if val > target:
                return False
            if current_sum + val <= target:
                current_sum += val
                i += 1
                elements_covered += 1
            else:
                count += 1
                current_sum = 0
                if count >= groups:
                    return False
        if current_sum > 0:
            count += 1
        return count <= groups

    def check(target):
        for s in range(n):
            if can_partition(target, s):
                return True
        return False
    low = max(values)
    high = sum(values)
    ans = high
    while low <= high:
        mid = (low + high) // 2
        if check(mid):
            ans = mid
            high = mid - 1
        else:
            low = mid + 1
    return ans

